def select(id,label,options):return f'<label for="{id}">{label}<select id="{id}">'+''.join(f'<option value="{v}">{t}</option>' for v,t in options)+'</select></label>'
def slider(id,label,mn,mx,step,v):return f'<label for="{id}">{label} <output id="{id}-out">{v}</output><input type="range" id="{id}" min="{mn}" max="{mx}" step="{step}" value="{v}"></label>'
