def demo(id,num,title,prompt,controls,extra='',canvas=True,note='',source='',anim=False):return f'''<section id="{id}-demo" class="demo" aria-labelledby="{id}-title"><header class="demo-head"><div><div class="demo-no">LAB {num} / 先预测 · 再操作 · 看证明</div><h4 id="{id}-title">{title}</h4></div>{'<button data-play aria-pressed="true">暂停动画</button>' if anim else ''}</header><div class="prompt">{prompt}</div><div class="demo-body">{'<canvas role="img" aria-label="'+title+'；通过下方控件操作"></canvas>' if canvas else ''}<div class="controls">{controls}</div>{extra}<div class="result" id="{id}-status" role="status" aria-live="off">载入模型后显示。</div><p class="note">{note}</p><details class="source-box"><summary>展开实际数值代码与实现说明</summary><pre><code data-source="{source or id}"></code></pre><div class="source-links"><a href="assets/groups.js" download>完整群运算 JS ↓</a><a href="examples.py" download>纯 Python 算例 ↓</a></div></details></div></section>'''
